def solution(C):
    n = len(C)

    # Create a copy of the cost matrix to avoid modifying the original
    C_prime = [[C[i][j] for j in range(n)] for i in range(n)]

    # Initialize the Hungarian algorithm
    row_covered = [False] * n
    col_covered = [False] * n

    def find_min_cost_cell(row, col):
        min_cost = float('inf')
        min_row = -1
        min_col = -1
        for i in range(n):
            for j in range(n):
                if not row_covered[i] and not col_covered[j] and C_prime[i][j] < min_cost:
                    min_cost = C_prime[i][j]
                    min_row = i
                    min_col = j
        return min_row, min_col

    def cover_row_col(row, col):
        row_covered[row] = True
        col_covered[col] = True

    # Iterate until all rows and columns are covered
    while not all(row_covered) or not all(col_covered):
        row, col = find_min_cost_cell(row_covered, col_covered)
        cover_row_col(row, col)

        # Update the cost matrix by subtracting the minimum cost from all cells in the covered row and column
        for i in range(n):
            for j in range(n):
                if row_covered[i] or col_covered[j]:
                    C_prime[i][j] -= min_cost

    # Calculate the total cost
    total_cost = 0
    for i in range(n):
        for j in range(n):
            if not row_covered[i] or not col_covered[j]:
                total_cost += C_prime[i][j]

    return int(total_cost)

