code_question:
def solution():
    distances = {
        0: {1: 88, 2: 188, 3: 80},
        1: {0: 88, 2: 121, 3: 96},
        2: {0: 188, 1: 121, 3: 42},
        3: {0: 80, 1: 96, 2: 42}
    }

    cities = list(distances.keys())
    n = len(cities)
    tsp_path = [0]
    total_distance = 0
    for i in range(n - 1):
        min_distance = float('inf')
        next_city = None
        for city in cities:
            if city not in tsp_path and distances[tsp_path[-1]][city] < min_distance:
                min_distance = distances[tsp_path[-1]][city]
                next_city = city
        tsp_path.append(next_city)
        total_distance += min_distance
    tsp_path.append(0)  # Return to the starting city
    return tsp_path, total_distance

